"""Seat-local record serialization and mechanical checks; no model calls."""
import hashlib
import json
import os
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path('/home/lingxufeng/ArxivDaily')
OUT = Path(__file__).parent
MAN = json.loads((OUT.parents[3] / 'manifest.json').read_text())
WEIGHTS = dict(zip(['G', 'M', 'X', 'E.measurement', 'E.causality', 'E.holdout', 'E.statistics', 'E.cost'], [15, 20, 20, 10, 15, 10, 5, 5]))
PARENTS = dict(line.split('\t') for line in (ROOT / 'research/reference/researchstudio-15-31/PARENTS.tsv').read_text().splitlines()[1:] if line.strip())

def emit(key: str, data: dict) -> None:
    target = OUT / f'{key}.json'
    if target.exists():
        return
    p = next(p for p in MAN['paper_details'] if p['paper_key'] == key)
    text = (ROOT / p['material']['text_path']).read_text()
    assert hashlib.sha256(text.encode()).hexdigest() == p['material']['sha256']
    evidence_kinds = data.pop('evidence_kinds', {})
    ev = []
    for i, (locator, quote, explanation) in enumerate(data.pop('quotes'), 1):
        assert quote in text, (key, quote)
        ev.append(dict(evidence_id=f'E{i:03}', material_id='fulltext', sha256=p['material']['sha256'], locator=locator, quote=quote, support_explanation=explanation, kind=evidence_kinds.get(f'E{i:03}', 'author_report')))
    rates = {}
    for axis, (value, reason, ids, search) in zip(WEIGHTS, data.pop('rating_data')):
        rates[axis] = dict(status='unknown' if value is None else ('not_reported' if search else 'resolved'), rating=value, reason=reason, evidence_ids=ids, counterevidence_ids=[], search_scope=search)
    lower = sum(WEIGHTS[k] * (v['rating'] or 0) / 4 for k, v in rates.items())
    coverage = sum(WEIGHTS[k] for k, v in rates.items() if v['status'] != 'unknown') / 100
    upper = lower + sum(WEIGHTS[k] for k, v in rates.items() if v['status'] == 'unknown')
    for m in data['rs_pattern']['matches']:
        assert m['sub_id'] is None or PARENTS[m['sub_id']] == m['main_id']
    status = data.pop('status', 'reviewed')
    complete = data.pop('material_complete', True)
    missing = data.pop('missing_sections', [])
    score = dict(raw=lower if coverage == 1 else None, display=round(lower + 1e-9, 1) if coverage == 1 else None, lower=lower, upper=upper, coverage=coverage, rubric_hash=MAN['rubric']['sha256'])
    if status in {'needs_fulltext', 'out_of_scope'}:
        score = None
        data['score_interval'] = dict(lower=lower, upper=upper, coverage=coverage)
    record = dict(schema_version='radar-review-v2.2', run_id=MAN['run_id'], batch_id='r01b', attempt_id='a1', seat='sol', paper=dict(paper_key=key, paper_id=p['arxiv'], title=p['title'], version=p['version'], claim_type='system_method', central_claim=data.pop('central_claim')), provenance=dict(input_hash=MAN['input_hash'], rubric_version='v2.2/frozen-v1.0', rubric_hash=MAN['rubric']['sha256'], rs_manifest_hash=MAN['assets']['rs_manifest']['sha256'], domain_cards_hash=MAN['assets']['domain_cards_dir']['sha256'], expectations_hash=MAN['assets']['domain_conditions']['sha256'], model_type='sol(gpt-6.1-sol)', actual_model='gpt-6.1-sol', session_id=None, receipt_ref=None, timestamp=datetime.now(timezone.utc).isoformat(), notes=['actual_model supplied by invocation environment; no independent routing probe performed.', 'No seat-specific session identifier or receipt exposed to this worker. Historical outcome sections of required pattern assets are not used as evidence or scoring inputs.']), materials=[dict(material_id='fulltext', url=p['material']['source_url'], version=p['version'], sha256=p['material']['sha256'], sections_read=data.pop('sections_read'), complete=complete, missing_sections=missing)], evidence=ev, ratings=rates, score=score, status=status, **data)
    ids = {e['evidence_id'] for e in ev}
    assert all(set(v['evidence_ids']) <= ids for v in rates.values())
    for v in rates.values():
        assert v['status'] != 'not_reported' or (v['rating'] == 0 and v['search_scope'])
    raw = json.dumps(record, ensure_ascii=False, indent=2) + '\n'
    tmp = target.with_suffix('.json.tmp')
    tmp.write_text(raw)
    json.loads(tmp.read_text())
    os.replace(tmp, target)
    print(key, record['status'], record['score']['raw'] if record['score'] else None)

def rs(main: str, sub: str | None, reason: str, ids: list[str], steps: list[str], checks: list[str]) -> dict:
    return dict(primary=main, supporting=[], matches=[dict(main_id=main, sub_id=sub, role='primary', fit='partial' if sub is None else 'high', tactic_steps_checked=steps, evidence_ids=ids, reason=reason, **{'success/failure_checks': checks})], outside_taxonomy=False, reason=reason, executes_pattern=True, resolves_problem=False)

def domain(main: str, sub: str | None, fit: str, checks: list[dict], ids: list[str]) -> dict:
    return dict(main=main, sub=sub, version='manifest-fixed-2026-10-21', fit=fit, condition_checks=checks, evidence_ids=ids)

def exp(id: str, source: str, when: str, status: str, reason: str, ids: list[str], axis: str) -> dict:
    return dict(id=id, version='manifest-fixed-2026-10-21', source_strength='single_source', source_refs=[source], applies_when=when, applicable=True, status=status, reason=reason, evidence_ids=ids, score_item=axis)

